def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def snapshot(account):
        return (account, balances.get(account), account in frozen)

    for i, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]
        valid = False

        if verb == "undo" and len(tokens) == 1:
            if history:
                for account, balance, was_frozen in history.pop():
                    if balance is None:
                        del balances[account]
                    else:
                        balances[account] = balance
                    if was_frozen:
                        frozen.add(account)
                    else:
                        frozen.discard(account)
                valid = True

        elif verb in ("freeze", "unfreeze") and len(tokens) == 2:
            account = tokens[1]
            if account in balances:
                if verb == "freeze" and account not in frozen:
                    history.append([snapshot(account)])
                    frozen.add(account)
                    valid = True
                elif verb == "unfreeze" and account in frozen:
                    history.append([snapshot(account)])
                    frozen.remove(account)
                    valid = True

        elif (
            (verb in ("open", "deposit", "withdraw") and len(tokens) == 3)
            or (verb == "transfer" and len(tokens) == 4)
        ):
            amount_text = tokens[-1]
            if amount_text and all("0" <= c <= "9" for c in amount_text):
                # Parse in small chunks to support amounts of any length.
                amount = 0
                for start in range(0, len(amount_text), 9):
                    chunk = amount_text[start:start + 9]
                    amount = amount * (10 ** len(chunk)) + int(chunk)

                account = tokens[1]

                if verb == "open":
                    if account not in balances:
                        history.append([snapshot(account)])
                        balances[account] = amount
                        valid = True

                elif verb == "deposit":
                    if amount > 0 and account in balances:
                        history.append([snapshot(account)])
                        balances[account] += amount
                        valid = True

                elif verb == "withdraw":
                    if (
                        amount > 0
                        and account in balances
                        and account not in frozen
                        and balances[account] >= amount
                    ):
                        history.append([snapshot(account)])
                        balances[account] -= amount
                        valid = True

                else:
                    destination = tokens[2]
                    if (
                        amount > 0
                        and account != destination
                        and account in balances
                        and destination in balances
                        and account not in frozen
                        and balances[account] >= amount
                    ):
                        history.append([snapshot(account), snapshot(destination)])
                        balances[account] -= amount
                        balances[destination] += amount
                        valid = True

        if not valid:
            rejected.append(i)

    return balances, rejected
